import{_ as o,o as r,c as t,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Tenant API v1 — Reseller Payouts","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Reseller Payouts | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-reseller-payouts"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Reseller Payouts | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-reseller-payouts"}]]},"headers":[],"relativePath":"api/tenant-v1-reseller-payouts.md","filePath":"api/tenant-v1-reseller-payouts.md","lastUpdated":1787485542000}'),i={name:"api/tenant-v1-reseller-payouts.md"};function s(c,e,d,n,l,p){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-reseller-payouts" tabindex="-1">Tenant API v1 — Reseller Payouts <a class="header-anchor" href="#tenant-api-v1-—-reseller-payouts" aria-label="Permalink to &quot;Tenant API v1 — Reseller Payouts&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:reseller-payouts</code>, plus permission middleware / policies.</p><p>Resource path prefix: <code>/reseller-commission-entries</code>.</p><p>Visibility: without <code>resellers.assign</code> (and not superadmin), list/stats/view are limited to rows where <code>party_user_id</code> is the current user, or the parent reseller’s linked <code>user_id</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-reseller-commission-entries-stats" tabindex="-1">GET <code>/reseller-commission-entries/stats</code> <a class="header-anchor" href="#get-reseller-commission-entries-stats" aria-label="Permalink to &quot;GET `/reseller-commission-entries/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload:</p><p><code>total</code>, <code>accrued</code>, <code>approved</code>, <code>paid</code>, <code>void</code>, <code>accrued_amount</code>, <code>approved_amount</code>, <code>paid_amount</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="list-show" tabindex="-1">List &amp; show <a class="header-anchor" href="#list-show" aria-label="Permalink to &quot;List &amp; show&quot;">​</a></h2><h3 id="get-reseller-commission-entries" tabindex="-1">GET <code>/reseller-commission-entries</code> <a class="header-anchor" href="#get-reseller-commission-entries" aria-label="Permalink to &quot;GET `/reseller-commission-entries`&quot;">​</a></h3><p>Query: <code>search</code> (reseller name/email/company_name or invoice number/title), <code>status</code> (<code>accrued</code>|<code>approved</code>|<code>paid</code>|<code>void</code>), <code>party</code> (<code>reseller</code>|<code>owner</code>), <code>reseller_id</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>Permission: <code>reseller-payouts.view</code>.</p><h3 id="get-reseller-commission-entries-id" tabindex="-1">GET <code>/reseller-commission-entries/{id}</code> <a class="header-anchor" href="#get-reseller-commission-entries-id" aria-label="Permalink to &quot;GET `/reseller-commission-entries/{id}`&quot;">​</a></h3><p>Includes <code>reseller</code>, <code>customer_invoice</code>, and <code>party_user</code> when loaded.</p><p>Permission: <code>reseller-payouts.view</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-reseller-commission-entries-id-approve" tabindex="-1">POST <code>/reseller-commission-entries/{id}/approve</code> <a class="header-anchor" href="#post-reseller-commission-entries-id-approve" aria-label="Permalink to &quot;POST `/reseller-commission-entries/{id}/approve`&quot;">​</a></h3><p>Accrued → approved. Sets <code>approved_at</code> / <code>approved_by</code>.</p><p>Permission: <code>reseller-payouts.approve</code>. Validation error if not accrued.</p><h3 id="post-reseller-commission-entries-id-pay" tabindex="-1">POST <code>/reseller-commission-entries/{id}/pay</code> <a class="header-anchor" href="#post-reseller-commission-entries-id-pay" aria-label="Permalink to &quot;POST `/reseller-commission-entries/{id}/pay`&quot;">​</a></h3><p>Approved → paid. Sets <code>paid_at</code> / <code>paid_by</code>.</p><p>Permission: <code>reseller-payouts.pay</code>. Validation error if not approved.</p><h3 id="post-reseller-commission-entries-id-void" tabindex="-1">POST <code>/reseller-commission-entries/{id}/void</code> <a class="header-anchor" href="#post-reseller-commission-entries-id-void" aria-label="Permalink to &quot;POST `/reseller-commission-entries/{id}/void`&quot;">​</a></h3><p>→ void (from accrued or approved). Sets <code>voided_at</code> / <code>voided_by</code>.</p><p>Permission: <code>reseller-payouts.void</code>. Rejects already void or <strong>paid</strong> status.</p><h2 id="accrual-event-driven-no-create-endpoint" tabindex="-1">Accrual (event-driven; no create endpoint) <a class="header-anchor" href="#accrual-event-driven-no-create-endpoint" aria-label="Permalink to &quot;Accrual (event-driven; no create endpoint)&quot;">​</a></h2><p>There is no public create endpoint. Rows are inserted by <code>ResellerCommissionService::accrueForPaidInvoice</code> when <code>CustomerInvoiceBecamePaid</code> fires, if:</p><ul><li>invoice has <code>reseller_id</code></li><li>tenant is entitled to <code>reseller-payouts</code></li><li>reseller exists</li></ul><p>Formula (per invoice total <code>T</code>):</p><ul><li>reseller amount = <code>round(T × commission_rate / 100, 2)</code></li><li>owner amount = <code>round((T − reseller amount) × owner_commission_rate / 100, 2)</code></li></ul><p>Idempotent unique key: <code>(customer_invoice_id, party)</code>.</p><p>Leaving Paid (<code>CustomerInvoiceLeftPaid</code>) calls <code>voidForInvoice</code>, which voids every non-void entry for that invoice. If the invoice becomes Paid again, accrual <strong>revives</strong> those void rows with refreshed snapshot amounts (same unique <code>(customer_invoice_id, party)</code> keys).</p>',33)])])}const h=o(i,[["render",s]]);export{u as __pageData,h as default};
